1|// Reader model: the slim shape the client receives. Joins paragraphs to
2|// scenes by ordinal range in reading order; analysis internals never leave.
3|import type { AnalyzedScene, Book } from "./types";
4|import type { Vector8 } from "./types";
5|
6|export interface ReaderParagraph {
7|  id: string;
8|  n: number;
9|  text: string;
10|}
11|
12|export interface ReaderScene {
13|  id: string;
14|  title: string;
15|  emotion: { vector: Vector8; intensity: number; tempo: number } | null;
16|  paragraphs: ReaderParagraph[];
17|}
18|
19|export interface ReaderChapter {
20|  ch: number;
21|  title: string;
22|  scenes: ReaderScene[];
23|}
24|
25|export interface ReaderModel {
26|  bookId: string;
27|  textVersion: string;
28|  title: string;
29|  author: string;
30|  chapters: ReaderChapter[];
31|}
32|
33|// 1280x800 fit: the reading column is 595 px tall and the heading block
34|// (kicker, title, Scene/Page line) takes ~115 px of it on every page,
35|// leaving ~480 px for text. At 20.5px/1.7 each line costs 34.85 px, so a
36|// page holds 13 lines; the ~538 px measure fits ~58 chars per line, so
37|// each paragraph costs ceil(chars / 58) lines and short dialogue lines
38|// each take a full line. Page one also carries the drop cap, so it
39|// budgets one less. Paragraphs stay whole; one over budget takes its own
40|// page.
41|export const PAGE_WORD_BUDGET = 250;
42|const READ_COL_PX = 595;
43|const HEADING_PX = 115;
44|const LINE_PX = 20.5 * 1.7;
45|export const CHARS_PER_LINE = 58;
46|export const LINES_PER_PAGE = Math.floor((READ_COL_PX - HEADING_PX) / LINE_PX);
47|export const FIRST_PAGE_LINES = LINES_PER_PAGE - 1;
48|
49|export interface SubPage {
50|  paragraphs: ReaderParagraph[];
51|  startN: number;
52|  endN: number;
53|  words: number;
54|}
55|
56|export function countWords(text: string): number {
57|  const words = text.split(/\s+/).filter((w) => w.length > 0);
58|  return words.length;
59|}
60|
61|export function estimateLines(text: string): number {
62|  return Math.max(1, Math.ceil(text.length / CHARS_PER_LINE));
63|}
64|
65|// Split one scene into sub-pages at paragraph boundaries: a page closes
66|// when the next paragraph would pass the word budget or the line budget.
67|export function paginateScene(
68|  paragraphs: ReaderParagraph[],
69|  budgetWords: number = PAGE_WORD_BUDGET,
70|): SubPage[] {
71|  const pages: SubPage[] = [];
72|  let current: ReaderParagraph[] = [];
73|  let words = 0;
74|  let lines = 0;
75|  const flush = () => {
76|    if (current.length === 0) return;
77|    pages.push({
78|      paragraphs: current,
79|      startN: current[0]?.n ?? 0,
80|      endN: current[current.length - 1]?.n ?? 0,
81|      words,
82|    });
83|    current = [];
84|    words = 0;
85|    lines = 0;
86|  };
87|  for (const p of paragraphs) {
88|    const w = countWords(p.text);
89|    const l = estimateLines(p.text);
90|    const budget = pages.length === 0 ? FIRST_PAGE_LINES : LINES_PER_PAGE;
91|    if (current.length > 0 && (words + w > budgetWords || lines + l > budget)) flush();
92|    current.push(p);
93|    words += w;
94|    lines += l;
95|  }
96|  flush();
97|  if (pages.length === 0) pages.push({ paragraphs: [], startN: 0, endN: 0, words: 0 });
98|  return pages;
99|}
100|
101|export interface SceneView {
102|  sceneId: string;
103|  ch: number;
104|  chapterTitle: string;
105|  title: string;
106|  emotion: ReaderScene["emotion"];
107|  pages: SubPage[];
108|  prevSceneId: string | null;
109|  nextSceneId: string | null;
110|  k: number;
111|  n: number;
112|}
113|
114|// The only text a scene route ships: this scene, its chapter, its pages,
115|// and neighbor ids for the pager. Throws on unknown scene id.
116|export function buildSceneView(
117|  model: ReaderModel,
118|  sceneId: string,
119|  budgetWords: number = PAGE_WORD_BUDGET,
120|): SceneView {
121|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
122|  const at = flat.findIndex((e) => e.scene.id === sceneId);
123|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
124|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
125|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
126|  const prev = at > 0 ? flat[at - 1] : null;
127|  const next = at < flat.length - 1 ? flat[at + 1] : null;
128|  return {
129|    sceneId,
130|    ch: entry.ch,
131|    chapterTitle: entry.chapterTitle,
132|    title: entry.scene.title,
133|    emotion: entry.scene.emotion,
134|    pages: paginateScene(entry.scene.paragraphs, budgetWords),
135|    prevSceneId: prev?.scene.id ?? null,
136|    nextSceneId: next?.scene.id ?? null,
137|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
138|    n: chapterScenes.length,
139|  };
140|}
141|
142|export interface NavState {
143|  sceneId: string;
144|  page: number;
145|}
146|
147|export type NavAction =
148|  | { kind: "next" }
149|  | { kind: "prev" }
150|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
151|
152|export interface NavIndex {
153|  order: string[];
154|  pageCounts: Map<string, number>;
155|}
156|
157|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
158|  return {
159|    order: views.map((v) => v.sceneId),
160|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
161|  };
162|}
163|
164|// Every pager move in one place: next/prev cross scenes and chapters,
165|// going back lands on the last sub-page, bounds are no-ops, unknown
166|// goto ids keep state.
167|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
168|  const at = index.order.indexOf(state.sceneId);
169|  if (at < 0) return state;
170|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
171|  if (action.kind === "next") {
172|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
173|    const nextId = index.order[at + 1];
174|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
175|  }
176|  if (action.kind === "prev") {
177|    if (state.page > 0) return { ...state, page: state.page - 1 };
178|    const prevId = at > 0 ? index.order[at - 1] : undefined;
179|    if (prevId === undefined) return state;
180|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
181|  }
182|  if (index.order.indexOf(action.sceneId) < 0) return state;
183|  const count = index.pageCounts.get(action.sceneId) ?? 1;
184|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
185|}
186|
187|// True only when the scene id changed. The container gates observeScene
188|// on this, so sub-page moves never touch the scheduler.
189|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
190|  return prevSceneId !== nextSceneId;
191|}
192|
193|export interface SceneEntryGate {
194|  observedId: string | null;
195|  routeId: string | null;
196|  manifestReady: boolean;
197|}
198|
199|// The container's effect gate in one testable place: observe exactly once
200|// per route id, only after the manifest lands. Route params can lag a
201|// render, so the last observed id is compared before every observe call.
202|export function nextSceneEntry(gate: SceneEntryGate): {
203|  shouldObserve: boolean;
204|  nextObservedId: string | null;
205|} {
206|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
207|    return { shouldObserve: false, nextObservedId: gate.observedId };
208|  }
209|  return { shouldObserve: true, nextObservedId: gate.routeId };
210|}
211|
212|// Throws on unordered scenes and on paragraphs covered zero or two times.
213|export function buildReaderModel(
214|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
215|  analysis: { scenes: AnalyzedScene[] },
216|): ReaderModel {
217|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
218|  const scenes = [...analysis.scenes];
219|  for (let i = 1; i < scenes.length; i++) {
220|    const prev = scenes[i - 1];
221|    const cur = scenes[i];
222|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
223|      throw new Error(`scenes out of order at ${cur.id}`);
224|    }
225|  }
226|  const seen = new Set<number>();
227|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
228|  for (const scene of scenes) {
229|    const paras: ReaderParagraph[] = [];
230|    for (let n = scene.start_n; n <= scene.end_n; n++) {
231|      const p = byN.get(n);
232|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
233|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
234|      seen.add(n);
235|      paras.push({ id: p.id, n: p.n, text: p.text });
236|    }
237|    sceneParagraphs.set(scene.id, paras);
238|  }
239|  if (seen.size !== book.paragraphs.length) {
240|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
241|  }
242|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
243|    const mine = scenes.filter((s) => s.ch === chapter.ch);
244|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
245|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
246|    }
247|    return {
248|      ch: chapter.ch,
249|      title: chapter.title,
250|      scenes: mine.map((s) => ({
251|        id: s.id,
252|        title: s.title,
253|        emotion: s.final === null ? null : { ...s.final },
254|        paragraphs: sceneParagraphs.get(s.id) ?? [],
255|      })),
256|    };
257|  });
258|  return {
259|    bookId: book.id,
260|    textVersion: book.textVersion,
261|    title: book.title,
262|    author: book.author,
263|    chapters,
264|  };
265|}

