agent-logs/16-fix1.jsonl:316:{"schema_version":1,"id":"018f0000-0000-7000-8000-00000000c5c3","stream":{"kind":"session","id":"01a182c1-9dd2-7121-9953-a4599a9aaca1"},"sequence":316,"recorded_at":1780531400000627,"record_type":"event","durability":"durable","causation_id":"01a182c1-9f7b-73f0-a727-372da805be8c","payload_type":"tool.result","payload_schema_version":1,"payload":{"call_id":"call_01a182c1ea0572d3876987ba15f33713","command_id":"01a182c1-9f7b-73f0-a727-372da805be8c","correlation_facts":{"outcome":"success","tool_name":"read_file"},"kind":"tool_result","run_stream":{"id":"01a182c1-9f7b-73f0-a727-372da805be8c","kind":"run"},"text":"Read text file `/workspace/wt-16/app/folio/use-pictures.ts`.
1|// Picture state for one scene: the pane card plus inline figures.
2|// The client sends ordinals and ids only, never text. Session caches
3|// survive sub-page and scene moves, so a shown picture never refetches.
4|"use client";
5|
6|import { useCallback, useEffect, useRef, useState } from "react";
7|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
8|import type { ImageResponse } from "@/core/images";
9|import { requestStyleFields, styleCredit } from "../image-style";
10|import type { ImageStylePref } from "../image-style";
11|import { pickEndN, pickStartN } from "../picture-selection";
12|import type { ParaEntry } from "../picture-selection";
13|
14|export type SceneCard =
15|  | { phase: "idle" }
16|  | { phase: "loading" }
17|  | { phase: "ready"; url: string; caption: string }
18|  | { phase: "error"; message: string };
19|
20|export interface InlineFigure {
21|  id: string;
22|  phase: "loading" | "ready" | "error";
23|  url: string | null;
24|  quote: string;
25|  startN: number;
26|  endN: number;
27|  credit: string;
28|  message: string | null;
29|}
30|
31|export interface LightboxItem {
32|  src: string;
33|  caption: string;
34|}
35|
36|const POLL_MS = 3000;
37|const POLL_MAX = 40;
38|
39|const sceneCache = new Map<string, { url: string; caption: string }>();
40|const figureCache = new Map<string, InlineFigure[]>();
41|let figureSeq = 1;
42|
43|function paraOf(node: Node | null): Element | null {
44|  if (!node) return null;
45|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
46|  return el?.closest?.("p[id]") ?? null;
47|}
48|
49|async function postImage(body: unknown): Promise<ImageResponse> {
50|  const res = await fetch("/api/images", {
51|    method: "POST",
52|    headers: { "Content-Type": "application/json" },
53|    body: JSON.stringify(body),
54|  });
55|  return (await res.json()) as ImageResponse;
56|}
57|
58|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
59|  let left = POLL_MAX;
60|  for (;;) {
61|    let res: ImageResponse;
62|    try {
63|      res = await postImage(body);
64|    } catch {
65|      throw new Error(MSG_FAILED);
66|    }
67|    if (res.status === "ready") return { url: res.url, caption: res.caption };
68|    if (res.status === "error") throw new Error(res.message);
69|    left -= 1;
70|    if (left <= 0) throw new Error(MSG_RETRY);
71|    await new Promise((done) => setTimeout(done, POLL_MS));
72|  }
73|}
74|
75|export function usePictures({
76|  bookId,
77|  textVersion,
78|  sceneId,
79|}: {
80|  bookId: string;
81|  textVersion: string;
82|  sceneId: string;
83|}) {
84|  const [card, setCard] = useState<SceneCard>(() => {
85|    const hit = sceneCache.get(sceneId);
86|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "idle" };
87|  });
88|  const [figures, setFigures] = useState<InlineFigure[]>(() =>
89|    (figureCache.get(sceneId) ?? []).filter((f) => f.phase !== "loading"),
90|  );
91|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
92|  const [lightbox, setLightbox] = useState<LightboxItem | null>(null);
93|  const viewRef = useRef<HTMLDivElement | null>(null);
94|  const popRef = useRef<HTMLButtonElement | null>(null);
95|  const openerRef = useRef<HTMLElement | null>(null);
96|  const busyRef = useRef(false);
97|
98|  const hidePopover = useCallback(() => setPopover(null), []);
99|
100|  const storeFigures = useCallback(
101|    (next: InlineFigure[] | ((prev: InlineFigure[]) => InlineFigure[])) => {
102|      setFigures((prev) => {
103|        const value = typeof next === "function" ? (next as (p: InlineFigure[]) => InlineFigure[])(prev) : next;
104|        figureCache.set(sceneId, value);
105|        return value;
106|      });
107|    },
108|    [sceneId],
109|  );
110|
111|  const openLightbox = useCallback((src: string, caption: string, opener: HTMLElement | null) => {
112|    openerRef.current = opener;
113|    setLightbox({ src, caption });
114|  }, []);
115|
116|  const closeLightbox = useCallback(() => {
117|    setLightbox(null);
118|    openerRef.current?.focus?.();
119|    openerRef.current = null;
120|  }, []);
121|
122|  const illustrateScene = useCallback(
123|    (pref: ImageStylePref) => {
124|      if (!sceneId || busyRef.current || sceneCache.has(sceneId)) return;
125|      busyRef.current = true;
126|      setPopover(null);
127|      setCard({ phase: "loading" });
128|      void poll({ kind: "scene", bookId, textVersion, sceneId, ...requestStyleFields(pref) })
129|        .then(({ url, caption }) => {
130|          sceneCache.set(sceneId, { url, caption });
131|          setCard({ phase: "ready", url, caption });
132|        })
133|        .catch((err: unknown) => {
134|          setCard({ phase: "error", message: err instanceof Error ? err.message : MSG_FAILED });
135|        })
136|        .finally(() => {
137|          busyRef.current = false;
138|        });
139|    },
140|    [bookId, textVersion, sceneId],
141|  );
142|
143|  const clearScene = useCallback(() => {
144|    sceneCache.delete(sceneId);
145|    setCard({ phase: "idle" });
146|  }, [sceneId]);
147|
148|  const requestFigure = useCallback(
149|    (id: string, startN: number, quote: string, pref: ImageStylePref) => {
150|      busyRef.current = true;
151|      void poll({ kind: "passage", bookId, textVersion, n: startN, ...requestStyleFields(pref) })
152|        .then(({ url }) => {
153|          storeFigures((prev) =>
154|            prev.map((f) => (f.id === id ? { ...f, phase: "ready", url, message: null } : f)),
155|          );
156|        })
157|        .catch((err: unknown) => {
158|          storeFigures((prev) =>
159|            prev.map((f) =>
160|              f.id === id
161|                ? { ...f, phase: "error", message: err instanceof Error ? err.message : MSG_FAILED }
162|                : f,
163|            ),
164|          );
165|        })
166|        .finally(() => {
167|          busyRef.current = false;
168|        });
169|    },
170|    [bookId, textVersion, storeFigures],
171|  );
172|
173|  const illustratePassage = useCallback(
174|    (pref: ImageStylePref) => {
175|      const view = viewRef.current;
176|      const sel = window.getSelection();
177|      if (!view || !sel || !sel.rangeCount || busyRef.current) return;
178|      const quote = sel.toString().trim();
179|      if (quote.length < 3) return;
180|      const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
181|        id: el.id,
182|        n: Number(el.getAttribute("data-n")),
183|      }));
184|      const startN = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
185|      const endN = pickEndN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
186|      if (startN === null || endN === null) return;
187|      setPopover(null);
188|      const id = `f${figureSeq++}`;
189|      const credit = styleCredit(requestStyleFields(pref));
190|      storeFigures((prev) => [
191|        ...prev,
192|        { id, phase: "loading", url: null, quote, startN, endN, credit, message: null },
193|      ]);
194|      requestFigure(id, startN, quote, pref);
195|    },
196|    [requestFigure, storeFigures],
197|  );
198|
199|  const retryFigure = useCallback(
200|    (id: string, pref: ImageStylePref) => {
201|      if (busyRef.current) return;
202|      const found = figureCache.get(sceneId)?.find((f) => f.id === id);
203|      if (!found || found.phase !== "error") return;
204|      storeFigures((prev) => prev.map((f) => (f.id === id ? { ...f, phase: "loading", message: null } : f)));
205|      requestFigure(id, found.startN, found.quote, pref);
206|    },
207|    [requestFigure, storeFigures, sceneId],
208|  );
209|
210|  const removeFigure = useCallback(
211|    (id: string) => {
212|      storeFigures((prev) => prev.filter((f) => f.id !== id));
213|    },
214|    [storeFigures],
215|  );
216|
217|  useEffect(() => {
218|    const view = viewRef.current;
219|    if (!view) return;
220|    let frame = 0;
221|    const onMouseUp = () => {
222|      cancelAnimationFrame(frame);
223|      frame = requestAnimationFrame(() => {
224|        const sel = window.getSelection();
225|        const text = sel?.toString().trim() ?? "";
226|        if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
227|          setPopover(null);
228|          return;
229|        }
230|        if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
231|          setPopover(null);
232|          return;
233|        }
234|        const box = sel.getRangeAt(0).getBoundingClientRect();
235|        const host = view.getBoundingClientRect();
236|        setPopover({
237|          top: box.top - host.top - 8,
238|          left: box.left - host.left + box.width / 2,
239|        });
240|      });
241|    };
242|    view.addEventListener("mouseup", onMouseUp);
243|    return () => {
244|      cancelAnimationFrame(frame);
245|      view.removeEventListener("mouseup", onMouseUp);
246|    };
247|  }, [sceneId]);
248|
249|  useEffect(() => {
250|    if (!popover) return;
251|    const onDown = (event: MouseEvent) => {
252|      if (!popRef.current?.contains(event.target as Node | null)) setPopover(null);
253|    };
254|    const onKey = (event: KeyboardEvent) => {
255|      if (event.key === "Escape") setPopover(null);
256|    };
257|    document.addEventListener("mousedown", onDown);
258|    document.addEventListener("keydown", onKey);
259|    return () => {
260|      document.removeEventListener("mousedown", onDown);
261|      document.removeEventListener("keydown", onKey);
262|    };
263|  }, [popover]);
264|
265|  return {
266|    card,
267|    figures,
268|    popover,
269|    viewRef,
270|    popRef,
271|    illustrateScene,
272|    illustratePassage,
273|    hidePopover,
274|    clearScene,
275|    removeFigure,
276|    retryFigure,
277|    lightbox,
278|    openLightbox,
279|    closeLightbox,
280|  };
281|}"}}
